#define Main void mainImage(out vec4 Q, in vec2 U)
#define R iResolution.xy
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)
#define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))
float smin( float a, float b, float k )
{
	float h = clamp( 0.5 + 0.5*(b-a)/k, 0.0, 1.0 );
	return mix( b, a, h ) - k*h*(1.0-h);
}
float smax(float a, float b, float k)
{
    return smin(a, b, -k);
}
vec4 hash(vec4 p4)
{
    p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}
float ln (vec3 u, vec3 a, vec3 b) {

    return length(u-a-(b-a)*clamp(dot(u-a,b-a)/dot(b-a,b-a),0.,1.));

}
float ellipsoid( vec3 p, vec3 r )
{
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1;
}

#define light 2.*vec3(-1,.8,-1)
vec2 map (vec3 p) {
    float d = 1e4;
    d = smin(d,ellipsoid(p,vec3(.3,.4,.3)),.1);
    d = smin(d,-ellipsoid(p-vec3(0,.05,0),vec3(.28,.42,.28)),-.02);
    d = smin(d,ln(p,vec3(0,-.4,0),vec3(0,-.7,0))-.02,.1);
    d = smin(d,ellipsoid(p-vec3(0,-.7,0),vec3(.2,.01,.2)),.1);
    d = smin(d,-ellipsoid(p-vec3(0,-.8,0),vec3(.6,.1,.6)),-.01);

    float w = ellipsoid(p,vec3(.28,.42,.28));
    w = smin(w,-.01*sin(20.*p.x)*sin(10.*p.z)+p.y,-.01);

    float f = p.y+.72;
    vec3 q = p-light;
    q.z = fract(q.z*0.5+0.5)*2.-1.;
    float l = length(q)-.1;
    if (w < d && w < f && w < l) return vec2(w,1.);
    if (f < d && f < l) return vec2(f,2.);
    if (l < d) return vec2(l,3.);
    return vec2(d,0.);
}
vec3 normal (vec3 p) {
    vec2 e = vec2(1e-4,0);
    float m = map(p).x;
    return normalize(vec3(
        map(p+e.xyy).x-m,
        map(p+e.yxy).x-m,
        map(p+e.yyx).x-m
    ));

}
Main {
    Q = A(U);
    vec3 p = vec3(0,-.2,-3);
    vec4 H = hash(vec4(iFrame,iTime,U));
    vec3 d = vec3(normalize(vec3(2.*(U+H.xy-.5*R)/R.y,6)));
    p.yz *= ei(-.6);
    d.yz *= ei(-.6);
    p += d*.5*H.z;
    vec4 q = max(sin(-2.+6.*H.w+vec4(1,2,3,4)),0.)*150.;
    for (float i = 0.; i < 200.; i++) {
        vec2 m = map(p);
        if (m.y==0.||m.y==1.) {
            p += d*max(abs(m.x),1e-5);
            if (abs(m.x)<2e-5) {
                vec4 h = hash(vec4(iFrame,U,i));
                if (h.w*2.-1. < 0.6) d = normalize(d-(.2+.02*H.w)*normal(p));
                else d = reflect(d,normal(p));
                p += 1e-4*d;
            }
            if (m.x < 0. && m.y==1.) {
                q *= 1.+2.*vec4(1,3,2,4)*m.x;
            }
        }
        if (m.y==3.) {
            p += d*m.x;
            if (m.x < 1e-5) {
                Q += q;
                break;
            }
        }
        if (m.y==2.) {
            p += d*m.x;
            if ((m.x) < 1e-4) {
                vec4 h = hash(vec4(iFrame,1,1,0));
                d = normalize(normalize(light-p)+.3*(h.xyz*2.-1.));
                p += 1e-4*d;
            }
        }
        if (m.x>10.) break;

    }

}
